import sys,os,re,collections,json
sys.path.insert(0,"/root/unitex-finrep/engine"); os.chdir("/root/unitex-finrep")
from odata_client import ODataClient
c=ODataClient()
vid={v["Ref_Key"]:(v.get("Description") or "").strip() for v in c.list("Catalog_ВидОплаты", select=["Ref_Key","Description"])}
cur={v["Ref_Key"]:(v.get("Description") or "").strip() for v in c.list("Catalog_Валюты", select=["Ref_Key","Description"])}
def num(x):
    try: return float(x or 0)
    except (TypeError,ValueError): return 0.0
IN=collections.defaultdict(float); OUT=collections.defaultdict(float); CU={}
n_in=n_out=0
for r in c.list("Document_Счет"):
    if str(r.get("СтатусСчета") or "")!="Оплачен": continue
    v=vid.get(r.get("видОплаты_Key"))
    if not v: continue
    IN[v]+=num(r.get("СуммаВал")); CU[v]=cur.get(r.get("Валюта_Key"),"?"); n_in+=1
for ent in ("Document_НакладныеРасходы","Document_РасходнаяНакладная"):
    for r in c.list(ent):
        if str(r.get("СтатусСчета") or "")!="Оплачен": continue
        v=vid.get(r.get("ВидОплаты_Key"))
        if not v: continue
        s=num(r.get("СуммаВал")) or num(r.get("Сумма"))
        OUT[v]+=s; CU.setdefault(v,cur.get(r.get("Валюта_Key"),"?")); n_out+=1
print("оплачених доходних: %d; оплачених витратних: %d"%(n_in,n_out),flush=True)
# те, що зараз у звіті (з ручного вивантаження)
REPORT={"Банк Юнітекс Ейч-Ді":182939.49,"Банк Юнітекс Форвардинг":31929.73,"Банк Юнітекс Ейч-Ді Восток":11559.45,
 "Каса USD UFWD":26193.46,"Каса USD UHD":19662.91,"Банк Cr String Cycle LLC":3699.88,"Банк Юнітекс Ейч-Ді EUR":0.0,
 "Каса USD Украмарин":-5682.60,"Маерск USD":1935.38,"Депозити USD":8000.0,"Каса UAH UFWD":3909.52,"Каса UAH UHD":13958.77}
print("\n%-28s %4s %14s %14s %14s %14s"%("ВИД ОПЛАТИ","вал","надійшло","виплачено","= розрахунок","у звіті"))
res={}
for v in sorted(set(IN)|set(OUT)|set(REPORT)):
    i,o=IN.get(v,0.0),OUT.get(v,0.0); calc=i-o; rep=REPORT.get(v)
    res[v]={"in":round(i,2),"out":round(o,2),"calc":round(calc,2),"report":rep}
    print("%-28s %4s %14.2f %14.2f %14.2f %14s"%(v[:28],CU.get(v,"?"),i,o,calc,("%.2f"%rep) if rep is not None else "—"))
json.dump(res,open("/root/direct-sync/cash_from_invoices.json","w"),ensure_ascii=False,indent=1)
PY
cd /root/direct-sync && nohup /root/unitex-finrep/.venv/bin/python cash_from_invoices.py > /root/direct-sync/cash_inv.out 2>&1 &
